// Terminals.
func (q *AccountQuery) Get() (*AccountRow, error) {
	row, err := q.GetOrNil()
	if err != nil {
		return nil, err
	}
	if row == nil {
		return nil, orm.ErrNoRows
	}
	return row, nil
}

// GetOrNil returns nil, nil when the query has no row.
func (q *AccountQuery) GetOrNil() (*AccountRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "one"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsAccountDirect, scanAccountDirect); used {
		if err != nil || len(direct) == 0 {
			return nil, err
		}
		return direct[0], nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil || len(rows.Data) == 0 {
		return nil, err
	}
	return scanAccount(rows.Data[0], rows.Assemble, rows), nil
}

func (q *AccountQuery) Gets() (*orm.Collection[AccountRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsAccountDirect, scanAccountDirect); used {
		if err != nil {
			return nil, err
		}
		return collectAccountDirect(direct, q.keyFn), nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return collectAccount(rows, q.keyFn), nil
}

// Stream visits independently owned rows without accumulating the complete result.
// Returning false stops the query and closes its database cursor.
func (q *AccountQuery) Stream(visit func(*AccountRow) bool) (orm.StreamResult, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.StreamResult{}, err
	}
	if visit == nil {
		return orm.StreamResult{}, &ir.Error{Code: orm.CodeIrInvalid, Msg: "stream visitor is required"}
	}
	q.q.Req.IR.Kind = "all"
	return orm.Stream(ctx, ex, q.q.Req, func(vals []any, rows *orm.Rows) bool {
		return visit(scanAccount(vals, rows.Assemble, rows))
	})
}

// GetsBySeq applies seq = v and runs the collection terminal.
func (q *AccountQuery) GetsBySeq(v int64) (*orm.Collection[AccountRow], error) {
	return q.Seq(v).Gets()
}

// GetsByName applies name = v and runs the collection terminal.
func (q *AccountQuery) GetsByName(v string) (*orm.Collection[AccountRow], error) {
	return q.Name(v).Gets()
}

func collectAccount(rows *orm.Rows, keyFn func(*AccountRow) orm.Key) *orm.Collection[AccountRow] {
	c := orm.NewCollection[AccountRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanAccount(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectAccountDirect(rows []*AccountRow, keyFn func(*AccountRow) orm.Key) *orm.Collection[AccountRow] {
	c := orm.NewCollection[AccountRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.Seq}), r)
		}
	}
	return c
}

// GetsAfter reads the next keyset page. An empty cursor starts at the first row.
func (q *AccountQuery) GetsAfter(cursor string, per int) (*orm.KeysetPage[AccountRow], error) {
	if err := q.q.Keyset("after", cursor, per, []string{"seq"}); err != nil {
		return nil, err
	}
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	items := collectAccount(rows, q.keyFn)
	return orm.KeysetPageFromRows(rows, items, q.q.Req.IR.Order)
}

// GetsBefore reads the previous keyset page and restores the requested order.
func (q *AccountQuery) GetsBefore(cursor string, per int) (*orm.KeysetPage[AccountRow], error) {
	if err := q.q.Keyset("before", cursor, per, []string{"seq"}); err != nil {
		return nil, err
	}
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	orm.ReverseRows(rows)
	items := collectAccount(rows, q.keyFn)
	return orm.KeysetPageFromRows(rows, items, q.q.Req.IR.Order)
}

